1	import * as React from "react";
2	import { Wallet, TrendingUp, PiggyBank, Mail, Plus, Save } from "lucide-react";
3	import type { EnvelopeRow } from "@contract";
4	import type { RolloverRule, EnvelopeType, BudgetPeriod } from "@domain";
5	import { call, isApiError, ApiCallError } from "@/lib/api";
6	import { useEnvelopeVersions, useInvalidateBudget } from "@/lib/queries";
7	import {
8	  cn,
9	  formatCents,
10	  normalisePeriods,
11	  monthlyEquivalentCents,
12	  displayInPeriod,
13	  todayIso,
14	  firstOfCurrentMonthIso,
15	  midMonthProrationNote,
16	  BUDGET_PERIODS,
17	  BUDGET_PERIOD_LABELS,
18	} from "@/lib/utils";
19	import {
20	  Dialog,
21	  DialogContent,
22	  DialogHeader,
23	  DialogTitle,
24	  DialogDescription,
25	  DialogFooter,
26	} from "@/components/ui/dialog";
27	import { Button } from "@/components/ui/button";
28	import { Input } from "@/components/ui/input";
29	import { Label } from "@/components/ui/label";
30	import { Checkbox } from "@/components/ui/checkbox";
31	import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from "@/components/ui/select";
32	
33	/** A normalised edit target the modal can populate from a grid row or income view. */
34	export interface BudgetEditTarget {
35	  readonly id: string;
36	  readonly name: string;
37	  readonly type: EnvelopeType;
38	  readonly active: boolean;
39	  readonly parentId: string | null;
40	  /** Monthly-equivalent template line for expense/saving/envelope envelopes. */
41	  readonly monthlyCents: number;
42	  /** The row's own period, so editing keeps the per-row period selector (ISC-94). */
43	  readonly period?: BudgetPeriod;
44	  /** The rollover schedule anchor date (YYYY-MM-DD), seeded into the date input. */
45	  readonly rolloverStart?: string | null;
46	  /** Income budget — the expected income, which is itself the balancing figure (income only). */
47	  readonly targetCents: number;
48	  /** Income only (D5): expected receipt day of month (1..31), or null. */
49	  readonly expectedDay?: number | null;
50	  /**
51	   * ADD-VERSION mode: append a NEW budget for this envelope (category-page
52	   * "Add budget"). The window keeps the add-flow defaults (From = first of
53	   * the current month) instead of seeding the active version's dates.
54	   */
55	  readonly addVersion?: boolean;
56	}
57	
58	interface Props {
59	  open: boolean;
60	  onOpenChange: (open: boolean) => void;
61	  /** Expense parent candidates (existing envelopes the new one can sit under). */
62	  rows: readonly EnvelopeRow[];
63	  /** When set, the modal edits this envelope instead of creating a new one (ISC-91/94/100). */
64	  editTarget?: BudgetEditTarget | null;
65	}
66	
67	const TYPE_OPTIONS: readonly { value: EnvelopeType; label: string; icon: typeof Wallet }[] = [
68	  { value: "income", label: "Income", icon: TrendingUp },
69	  { value: "expense", label: "Expense", icon: Wallet },
70	  { value: "saving", label: "Saving", icon: PiggyBank },
71	  { value: "envelope", label: "Envelope", icon: Mail },
72	];
73	
74	function centsToInput(cents: number): string {
75	  return cents ? (cents / 100).toFixed(2) : "";
76	}
77	
78	/**
79	 * Add / Edit budget modal (ISC-87, ISC-91, ISC-92, ISC-94, ISC-100).
80	 *
81	 * A four-way type toggle picks Income, Expense, Saving, or Envelope (ISC-91).
82	 * Saving and Envelope render like an expense (they just group differently
83	 * downstream). For income the field is the expected income, which is itself the
84	 * zero-base balancing figure (no separate capital sub-pool). For the spending
85	 * types the user enters a price in a chosen period and the modal live-normalises
86	 * it into all four periods as they type, mirroring Nick's spreadsheet. Type and
87	 * parent/category are editable on an existing envelope, not only at creation. An
88	 * Active toggle excludes an envelope from the budget total without deleting it.
89	 * Posts to POST /api/envelopes (create) or POST /api/envelopes/edit (edit).
90	 */
91	export function AddBudgetModal({ open, onOpenChange, rows, editTarget }: Props) {
92	  const invalidateBudget = useInvalidateBudget();
93	  const isEdit = Boolean(editTarget);
94	  // Edit mode: the chronology, so the window fields seed from the ACTIVE
95	  // version's REAL dates (owner correction 2026-08-12) — only the add-new flow
96	  // defaults to the first of the month.
97	  const versionsQuery = useEnvelopeVersions(editTarget?.id ?? "", { enabled: open && isEdit });
98	  const activeVersion = React.useMemo(() => {
99	    const data = versionsQuery.data;
100	    if (!data || isApiError(data) || !Array.isArray((data as { versions?: unknown }).versions)) return null;
101	    return data.versions.find((v) => v.status === "active") ?? null;
102	  }, [versionsQuery.data]);
103	
104	  const [type, setType] = React.useState<EnvelopeType>("expense");
105	  const [name, setName] = React.useState("");
106	  const [parentId, setParentId] = React.useState<string>("__top__");
107	  const [rolloverRule, setRolloverRule] = React.useState<RolloverRule>("roll_carry");
108	  // Expense / saving: price entered in a chosen period.
109	  const [price, setPrice] = React.useState("");
110	  const [period, setPeriod] = React.useState<BudgetPeriod>("monthly");
111	  // The rollover schedule anchor: a new budget resets at its interval from this date,
112	  // and editing it re-anchors the schedule (and so the running balances + Left).
113	  const [rolloverStart, setRolloverStart] = React.useState<string>("");
114	  // Income: the expected income (the budget), which is itself the balancing figure.
115	  const [target, setTarget] = React.useState("");
116	  // D5: the day of month the income is EXPECTED to land; the month's budget
117	  // becomes due on that day (blank = due from day 1).
118	  const [expectedDay, setExpectedDay] = React.useState("");
119	  // Budget chronology (Feature A): the version's effective window and whether
120	  // the previous version is completed. Default From = first of the CURRENT
121	  // month; move it forward to schedule the change (e.g. income as of 1 Aug).
122	  const [effectiveFrom, setEffectiveFrom] = React.useState<string>(firstOfCurrentMonthIso());
123	  const [effectiveTo, setEffectiveTo] = React.useState<string>("");
124	  // 409 scheduled_conflict: the save would cover a future-scheduled budget;
125	  // replacing it requires this explicit retry (doctrine D3).
126	  const [scheduledConflict, setScheduledConflict] = React.useState<string | null>(null);
127	  const [busy, setBusy] = React.useState(false);
128	  const [error, setError] = React.useState<string | null>(null);
129	
130	  // Reset the form when the modal OPENS (or the target changes) — keyed by
131	  // value, not object identity: a parent passing a fresh editTarget object on
132	  // every render must not re-run the reset mid-edit (that clobbered the
133	  // seeded real start date back to the 1st, and user typing with it).
134	  const resetKeyRef = React.useRef<string | null>(null);
135	  React.useEffect(() => {
136	    const key = open ? `${editTarget?.id ?? "new"}:${editTarget?.addVersion === true}` : null;
137	    if (!open) {
138	      resetKeyRef.current = null;
139	      return;
140	    }
141	    if (resetKeyRef.current === key) return;
142	    resetKeyRef.current = key;
143	    setError(null);
144	    setBusy(false);
145	    if (editTarget) {
146	      setType(editTarget.type);
147	      setName(editTarget.name);
148	      setParentId(editTarget.parentId ?? "__top__");
149	      setRolloverRule("roll_carry");
150	      // Keep the row's own period (ISC-94): seed both the selector and the price
151	      // converted out of its stored monthly equivalent into that period.
152	      {
153	        const rowPeriod = editTarget.period ?? "monthly";
154	        setPeriod(rowPeriod);
155	        setPrice(centsToInput(displayInPeriod(editTarget.monthlyCents, rowPeriod)));
156	      }
157	      setRolloverStart(editTarget.rolloverStart ?? "");
158	      // Income seeds in its OWN cadence (the stored figure is monthly-equivalent).
159	      setTarget(centsToInput(displayInPeriod(editTarget.targetCents, editTarget.period ?? "monthly")));
160	      setExpectedDay(editTarget.expectedDay != null ? String(editTarget.expectedDay) : "");
161	      // Prefilled with the familiar first-of-month; once the chronology loads
162	      // (below) a REAL dated active version replaces it with its actual window.
163	      // A legacy open-since-forever (1970) budget keeps this default — the
164	      // "Currently effective since the start" note explains — so the field is
165	      // always prefilled. Add-version mode keeps the add-flow defaults.
166	      setEffectiveFrom(firstOfCurrentMonthIso());
167	      setEffectiveTo("");
168	      setScheduledConflict(null);
169	      seededWindowRef.current = editTarget.addVersion === true;
170	    } else {
171	      setType("expense");
172	      setName("");
173	      setParentId("__top__");
174	      setRolloverRule("roll_carry");
175	      setPeriod("monthly");
176	      setPrice("");
177	      setRolloverStart(todayIso());
178	      setTarget("");
179	      setExpectedDay("");
180	      setEffectiveFrom(firstOfCurrentMonthIso());
181	      setEffectiveTo("");
182	      setScheduledConflict(null);
183	    }
184	  }, [open, editTarget]);
185	
186	  // Seed the window fields from the ACTIVE version exactly once per open —
187	  // the async chronology must never clobber dates the user already touched.
188	  const seededWindowRef = React.useRef(false);
189	  React.useEffect(() => {
190	    if (!open || !isEdit || seededWindowRef.current || activeVersion === null) return;
191	    seededWindowRef.current = true;
192	    if (activeVersion.effectiveFrom !== "1970-01-01") {
193	      setEffectiveFrom(activeVersion.effectiveFrom);
194	      setEffectiveTo(activeVersion.effectiveTo ?? "");
195	    }
196	    // The version is the authoritative plan rate: re-seed cadence + amount from
197	    // it (the row's allocation is materialised/prorated/range-summed, so it can
198	    // disagree with the plan the user is editing).
199	    if (editTarget?.addVersion !== true) {
200	      setPeriod(activeVersion.period);
201	      if (type === "income") {
202	        setTarget(centsToInput(displayInPeriod(activeVersion.amountCents, activeVersion.period)));
203	      } else {
204	        setPrice(centsToInput(displayInPeriod(activeVersion.amountCents, activeVersion.period)));
205	      }
206	    }
207	  }, [open, isEdit, activeVersion, editTarget, type]);
208	
209	  const dollarsToCents = (v: string) => Math.round((parseFloat(v) || 0) * 100);
210	  const priceCents = dollarsToCents(price);
211	  const targetCents = dollarsToCents(target);
212	
213	  // Live normalisation across all four periods (spending AND income entries).
214	  const normalised = React.useMemo(() => normalisePeriods(priceCents, period), [priceCents, period]);
215	  const normalisedIncome = React.useMemo(
216	    () => normalisePeriods(monthlyEquivalentCents(targetCents, period), "monthly"),
217	    [targetCents, period],
218	  );
219	
220	  const isIncome = type === "income";
221	  const canSubmit = name.trim().length > 0 && !busy;
222	  // Mid-month From: the first month is prorated by days (owner decision 2026-07-16).
223	  const prorationNote = midMonthProrationNote(effectiveFrom);
224	
225	  const onSubmit = async (supersede = false) => {
226	    if (!canSubmit) return;
227	    setBusy(true);
228	    setError(null);
229	    setScheduledConflict(null);
230	    try {
231	      if (isEdit && editTarget) {
232	        // BUDGET-ONLY edit (owner decision 2026-08-12): the widget never edits
233	        // category identity (name/type/parent), the rollover anchor, or the
234	        // expected day — those live in the category page's Edit category. The
235	        // amount lands as an effective-dated version; income entries convert
236	        // from their cadence to the monthly equivalent with the label kept.
237	        const incomeMonthly = monthlyEquivalentCents(targetCents, period);
238	        const res = await call("POST /api/envelopes/edit", {
239	          id: editTarget.id,
240	          ...(isIncome
241	            ? { targetCents: incomeMonthly, budgetedCents: incomeMonthly, period }
242	            : // The engine stores MONTHLY-EQUIVALENT cents with the cadence as a
243	              // label; a raw weekly 2200 here landed as $22/month (owner report
244	              // 2026-08-12: "$22 weekly saved as $22 monthly").
245	              { budgetedCents: monthlyEquivalentCents(priceCents, period), period }),
246	          // A cleared date input yields "" which the strict date schema 400s —
247	          // omit it and the server defaults to the first of the current month.
248	          ...(effectiveFrom ? { effectiveFrom } : {}),
249	          ...(effectiveTo ? { effectiveTo } : {}),
250	          ...(supersede ? { supersedeScheduled: true } : {}),
251	        });
252	        if (isApiError(res)) {
253	          setError(res.error);
254	          return;
255	        }
256	      } else {
257	        const incomeMonthly = monthlyEquivalentCents(targetCents, period);
258	        const res = await call("POST /api/envelopes", {
259	          name: name.trim(),
260	          type,
261	          ...(isIncome
262	            ? {
263	                parentId: null,
264	                targetCents: incomeMonthly,
265	                budgetedCents: incomeMonthly,
266	              }
267	            : {
268	                parentId: parentId !== "__top__" ? parentId : null,
269	                rolloverRule,
270	                budgetedCents: monthlyEquivalentCents(priceCents, period),
271	                period,
272	                ...(rolloverStart ? { rolloverStart } : {}),
273	                // A new envelope's first budget version starts here ("" omitted).
274	                ...(effectiveFrom ? { effectiveFrom } : {}),
275	                ...(effectiveTo ? { effectiveTo } : {}),
276	              }),
277	        });
278	        if (isApiError(res)) {
279	          setError(res.error);
280	          return;
281	        }
282	        // The create route has no expectedDay field; persist it via a follow-up
283	        // edit so an income created with a payday keeps it (D5).
284	        if (isIncome && expectedDay) {
285	          const created = res as { id: string };
286	          await call("POST /api/envelopes/edit", {
287	            id: created.id,
288	            expectedDay: Math.min(31, Math.max(1, Number(expectedDay))),
289	          });
290	        }
291	      }
292	      invalidateBudget();
293	      onOpenChange(false);
294	    } catch (e) {
295	      // Surface the server's ACTUAL message (call() throws ApiCallError with the
296	      // ApiError body's text on any non-2xx) so a rejected create — e.g. a stale
297	      // deploy refusing a valid envelope type — is diagnosable from the UI.
298	      if (e instanceof ApiCallError && e.code === "scheduled_conflict") {
299	        setScheduledConflict(e.message);
300	      } else {
301	        setError(e instanceof ApiCallError || e instanceof Error ? e.message : "Could not save the envelope.");
302	      }
303	    } finally {
304	      setBusy(false);
305	    }
306	  };
307	
308	  return (
309	    <Dialog open={open} onOpenChange={onOpenChange}>
310	      <DialogContent>
311	        <DialogHeader>
312	          <DialogTitle>{editTarget?.addVersion ? `Add budget — ${editTarget.name}` : isEdit ? "Edit budget" : "Add budget"}</DialogTitle>
313	          <DialogDescription>
314	            Choose whether this is income you expect, an expense you spend, or money you set aside as savings.
315	          </DialogDescription>
316	        </DialogHeader>
317	
318	        {/* Category identity (type, name, parent) is set at CREATE time only —
319	            editing it lives in the category page's "Edit category" (owner
320	            decision 2026-08-12: the budget widget never renames a category). */}
321	        {!isEdit && (
322	        <div className="space-y-2">
323	          <Label>Type</Label>
324	          <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
325	            {TYPE_OPTIONS.map(({ value, label, icon: Icon }) => (
326	              <button
327	                key={value}
328	                type="button"
329	                onClick={() => setType(value)}
330	                className={cn(
331	                  "flex items-center justify-center gap-1.5 rounded-md border px-2 py-2 text-sm font-medium transition-colors",
332	                  type === value ? "border-primary bg-primary text-primary-foreground" : "hover:bg-accent"
333	                )}
334	              >
335	                <Icon className="h-4 w-4" /> {label}
336	              </button>
337	            ))}
338	          </div>
339	          {(type === "saving" || type === "envelope") && (
340	            <p className="text-xs text-muted-foreground">
341	              {type === "saving" ? "Savings are" : "Envelopes are"} budgeted out just like an expense.
342	            </p>
343	          )}
344	        </div>
345	        )}
346	
347	        {!isEdit && (
348	        <div className="space-y-2">
349	          <Label htmlFor="env-name">Name</Label>
350	          <Input
351	            id="env-name"
352	            placeholder={isIncome ? "e.g. Salary — Primary" : type === "saving" ? "e.g. Holiday Fund" : "e.g. Groceries"}
353	            value={name}
354	            onChange={(e) => setName(e.target.value)}
355	          />
356	        </div>
357	        )}
358	
359	        {/* Parent applies to spending types at CREATE; edits via Edit category. */}
360	        {!isEdit && !isIncome && (
361	          <div className="space-y-2">
362	            <Label>Parent / category</Label>
363	            <Select value={parentId} onValueChange={setParentId}>
364	              <SelectTrigger>
365	                <SelectValue />
366	              </SelectTrigger>
367	              <SelectContent>
368	                <SelectItem value="__top__">Top level (no parent)</SelectItem>
369	                {rows
370	                  .filter((r) => r.id !== editTarget?.id)
371	                  .map((r) => (
372	                    <SelectItem key={r.id} value={r.id}>
373	                      {r.name}
374	                    </SelectItem>
375	                  ))}
376	              </SelectContent>
377	            </Select>
378	          </div>
379	        )}
380	
381	        {isIncome ? (
382	          /* Income: expected income entered in ANY cadence (weekly, fortnightly,
383	             monthly, annual) and normalised to its monthly equivalent — the
384	             zero-base stays monthly (owner request 2026-08-12). */
385	          <div className="space-y-3">
386	            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
387	              <div className="space-y-2">
388	                <Label htmlFor="income-target">Expected income (AUD)</Label>
389	                <Input
390	                  id="income-target"
391	                  type="number"
392	                  min="0"
393	                  step="0.01"
394	                  inputMode="decimal"
395	                  placeholder="0.00"
396	                  value={target}
397	                  onChange={(e) => setTarget(e.target.value)}
398	                />
399	              </div>
400	              <div className="space-y-2">
401	                <Label>Period</Label>
402	                <Select value={period} onValueChange={(v) => setPeriod(v as BudgetPeriod)}>
403	                  <SelectTrigger aria-label="Income budget period">
404	                    <SelectValue />
405	                  </SelectTrigger>
406	                  <SelectContent>
407	                    {BUDGET_PERIODS.map((p) => (
408	                      <SelectItem key={p} value={p}>
409	                        {BUDGET_PERIOD_LABELS[p]}
410	                      </SelectItem>
411	                    ))}
412	                  </SelectContent>
413	                </Select>
414	              </div>
415	            </div>
416	            <div className="grid grid-cols-4 gap-2 rounded-md border bg-muted/40 p-2 text-center">
417	              {BUDGET_PERIODS.map((p) => (
418	                <div key={p} className={cn("rounded px-1 py-1", p === period && "bg-primary/10")}>
419	                  <div className="text-[10px] uppercase tracking-wide text-muted-foreground">
420	                    {BUDGET_PERIOD_LABELS[p]}
421	                  </div>
422	                  <div className="tnum text-sm font-medium">{formatCents(normalisedIncome[p])}</div>
423	                </div>
424	              ))}
425	            </div>
426	            <p className="text-xs text-muted-foreground">
427	              The expected income for this source. It is the figure the zero-base balances against.
428	            </p>
429	            {!isEdit && (
430	            <div className="space-y-1">
431	              <Label htmlFor="income-expected-day">Expected on day of month (optional)</Label>
432	              <Input
433	                id="income-expected-day"
434	                type="number"
435	                min="1"
436	                max="31"
437	                inputMode="numeric"
438	                placeholder="e.g. 11"
439	                value={expectedDay}
440	                onChange={(e) => setExpectedDay(e.target.value)}
441	              />
442	              <p className="text-xs text-muted-foreground">
443	                Until this day the envelope reads carryover + received; from this day the month's income is
444	                due, so a missing payment shows as a deficit. Blank = due from day 1.
445	              </p>
446	            </div>
447	            )}
448	          </div>
449	        ) : (
450	          /* Expense / saving: price + period with live four-period normalisation (ISC-94) */
451	          <div className="space-y-3">
452	            <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
453	              <div className="space-y-2">
454	                <Label htmlFor="env-price">Price (AUD)</Label>
455	                <Input
456	                  id="env-price"
457	                  type="number"
458	                  min="0"
459	                  step="0.01"
460	                  inputMode="decimal"
461	                  placeholder="0.00"
462	                  value={price}
463	                  onChange={(e) => setPrice(e.target.value)}
464	                />
465	              </div>
466	              <div className="space-y-2">
467	                <Label>Period</Label>
468	                <Select value={period} onValueChange={(v) => setPeriod(v as BudgetPeriod)}>
469	                  <SelectTrigger>
470	                    <SelectValue />
471	                  </SelectTrigger>
472	                  <SelectContent>
473	                    {BUDGET_PERIODS.map((p) => (
474	                      <SelectItem key={p} value={p}>
475	                        {BUDGET_PERIOD_LABELS[p]}
476	                      </SelectItem>
477	                    ))}
478	                  </SelectContent>
479	                </Select>
480	              </div>
481	            </div>
482	            {/* Live equivalents in all four periods, recomputed as the user types. */}
483	            <div className="grid grid-cols-4 gap-2 rounded-md border bg-muted/40 p-2 text-center">
484	              {BUDGET_PERIODS.map((p) => (
485	                <div key={p} className={cn("rounded px-1 py-1", p === period && "bg-primary/10")}>
486	                  <div className="text-[10px] uppercase tracking-wide text-muted-foreground">
487	                    {BUDGET_PERIOD_LABELS[p]}
488	                  </div>
489	                  <div className="tnum text-sm font-medium">{formatCents(normalised[p])}</div>
490	                </div>
491	              ))}
492	            </div>
493	            {/* Rollover start date at CREATE only; edits via Edit category. */}
494	            {!isEdit && (
495	            <div className="space-y-2">
496	              <Label htmlFor="env-rollover">Rollover start date</Label>
497	              <Input
498	                id="env-rollover"
499	                type="date"
500	                max={todayIso()}
501	                value={rolloverStart}
502	                onChange={(e) => setRolloverStart(e.target.value)}
503	              />
504	              <p className="text-xs text-muted-foreground">
505	                The budget resets at the chosen interval from this date (e.g. 1 July for an annual budget).
506	              </p>
507	            </div>
508	            )}
509	          </div>
510	        )}
511	
512	        {/* Budget chronology (Feature A): when this budget version applies. The
513	            default From (first of the current month) matches today's edit
514	            semantics; a future From schedules the change (e.g. 1 Aug). Hidden
515	            when CREATING an income — a brand-new income has no version window,
516	            its chronology starts on the first edit. */}
517	        {!(isIncome && !isEdit) && (
518	        <div className="space-y-2">
519	          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
520	            <div className="space-y-2">
521	              <Label htmlFor="budget-from">Budget from</Label>
522	              <Input
523	                id="budget-from"
524	                type="date"
525	                value={effectiveFrom}
526	                onChange={(e) => setEffectiveFrom(e.target.value)}
527	              />
528	            </div>
529	            <div className="space-y-2">
530	              <Label htmlFor="budget-to">Budget until (optional)</Label>
531	              <Input
532	                id="budget-to"
533	                type="date"
534	                min={effectiveFrom}
535	                value={effectiveTo}
536	                onChange={(e) => setEffectiveTo(e.target.value)}
537	              />
538	            </div>
539	          </div>
540	          {prorationNote && <p className="text-xs text-muted-foreground">{prorationNote}</p>}
541	          {isEdit && activeVersion !== null && (
542	            <p className="text-xs text-muted-foreground">
543	              Currently effective{" "}
544	              {activeVersion.effectiveFrom === "1970-01-01" ? "since the start" : `from ${activeVersion.effectiveFrom}`}
545	              {activeVersion.effectiveTo ? ` until ${activeVersion.effectiveTo}` : " — ongoing"}.
546	              {activeVersion.effectiveFrom === "1970-01-01" &&
547	                " A blank From applies the change from the first of this month, keeping earlier months as they were."}
548	            </p>
549	          )}
550	          <p className="text-xs text-muted-foreground">
551	            The previous budget ends the day before this one starts — budgets never overlap. A budget
552	            scheduled for a future date is never replaced without asking.
553	          </p>
554	        </div>
555	        )}
556	
557	        {/* Rollover rule applies to expense/saving only. */}
558	        {!isIncome && !isEdit && (
559	          <div className="space-y-2">
560	            <Label>Rollover rule</Label>
561	            <Select value={rolloverRule} onValueChange={(v) => setRolloverRule(v as RolloverRule)}>
562	              <SelectTrigger>
563	                <SelectValue />
564	              </SelectTrigger>
565	              <SelectContent>
566	                <SelectItem value="roll_carry">Roll carry</SelectItem>
567	                <SelectItem value="drain_to_zero">Use or lose</SelectItem>
568	                <SelectItem value="annual_reset">Annual reset</SelectItem>
569	              </SelectContent>
570	            </Select>
571	          </div>
572	        )}
573	
574	        {/* The Active toggle is GONE (owner decision 2026-08-12): whether a
575	            budget is active is derived from its version dates — a budget whose
576	            window covers the viewed period is active; an ended or not-yet-
577	            started one is not. End a budget with an end date, not a switch. */}
578	
579	        {error && <p className="text-sm text-destructive">{error}</p>}
580	        {scheduledConflict && (
581	          <div className="space-y-2 rounded-lg border border-warning/40 bg-warning/10 px-3 py-2 text-sm">
582	            <p className="font-medium">{scheduledConflict}</p>
583	            <Button variant="outline" size="sm" disabled={busy} onClick={() => void onSubmit(true)}>
584	              Replace scheduled budgets and save
585	            </Button>
586	          </div>
587	        )}
588	
589	        <DialogFooter>
590	          <Button variant="outline" onClick={() => onOpenChange(false)}>
591	            Cancel
592	          </Button>
593	          <Button onClick={() => void onSubmit()} disabled={!canSubmit}>
594	            {isEdit && !editTarget?.addVersion ? <Save className="h-4 w-4" /> : <Plus className="h-4 w-4" />}{" "}
595	            {busy ? "Saving…" : editTarget?.addVersion ? "Add budget" : isEdit ? "Save changes" : "Add budget"}
596	          </Button>
597	        </DialogFooter>
598	      </DialogContent>
599	    </Dialog>
600	  );
601	}
