// keyboard would cover the options the user came to tap.
React.useEffect(() => {
  if (!showSearch || window.matchMedia("(pointer: coarse)").matches) return;
  const t = setTimeout(() => inputRef.current?.focus(), 10);
  return () => clearTimeout(t);
}, [showSearch]);

input.new_string:
// Autofocus the search box on fine pointers only — on touch the on-screen
// keyboard would cover the options the user came to tap. Radix runs its own
// focus pass on open, so claim focus after it (with one retry).
React.useEffect(() => {
  if (!showSearch || window.matchMedia("(pointer: coarse)").matches) return;
  const timers = [50, 200].map((ms) =>
    setTimeout(() => {
      if (document.activeElement !== inputRef.current) inputRef.current?.focus();
    }, ms),
  );
  return () => timers.forEach(clearTimeout);
}, [showSearch]);

