1	// Post-fix probes: Escape layering (ISC-217), search behaviour (ISC-225/226/228/231/245),
2	// pinned sentinel (ISC-227), reset-on-close (ISC-232), no-autofocus-on-touch (ISC-242).
3	import puppeteer from "puppeteer";
4	
5	const BASE = "http://127.0.0.1:8899";
6	const out = {};
7	
8	async function signIn(page) {
9	  await page.goto(`${BASE}/`, { waitUntil: "networkidle0" });
10	  if (page.url().includes("/signin")) {
11	    await page.waitForSelector('input[type="password"]');
12	    await page.type('input[type="password"]', "1234");
13	    await page.click('button[type="submit"]');
14	    await page.waitForNavigation({ waitUntil: "networkidle0" }).catch(() => {});
15	  }
16	}
17	
18	async function openAddBudget(page) {
19	  await page.waitForFunction(
20	    () => [...document.querySelectorAll("button")].some((b) => b.textContent.trim() === "Add budget"),
21	    { timeout: 15000 },
22	  );
23	  await page.evaluate(() => {
24	    [...document.querySelectorAll("button")].find((b) => b.textContent.trim() === "Add budget").click();
25	  });
26	  await page.waitForSelector('[role="dialog"]', { timeout: 5000 });
27	}
28	
29	// Seed a few envelopes via the API so the parent picker is a real list.
30	async function seedEnvelopes(page) {
31	  await page.evaluate(async () => {
32	    const names = ["Zebra Fund", "Groceries", "alpha utilities", "Mortgage", "Car", "Holidays", "Beach Gear"];
33	    for (const name of names) {
34	      await fetch("/api/envelopes", {
35	        method: "POST",
36	        headers: { "Content-Type": "application/json" },
37	        body: JSON.stringify({ name, type: "expense", parentId: null, rolloverRule: "roll_carry", budgetedCents: 1000, period: "monthly" }),
38	      });
39	    }
40	  });
41	}
42	
43	const state = (page) =>
44	  page.evaluate(() => ({
45	    dialog: Boolean(document.querySelector('[role="dialog"]')),
46	    listbox: Boolean(document.querySelector('[role="listbox"]')),
47	  }));
48	
49	async function combo(page, idx) {
50	  return page.evaluate((i) => {
51	    const dlg = document.querySelector('[role="dialog"]');
52	    const el = dlg?.querySelectorAll('[role="combobox"]')[i];
53	    if (!el) return null;
54	    const r = el.getBoundingClientRect();
55	    return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
56	  }, idx);
57	}
58	
59	const browser = await puppeteer.launch({ headless: "new", args: ["--no-sandbox"] });
60	try {
61	  const page = await browser.newPage();
62	  await page.setViewport({ width: 1280, height: 900 });
63	  await signIn(page);
64	  await seedEnvelopes(page);
65	  await page.reload({ waitUntil: "networkidle0" });
66	
67	  // --- Escape layering (ISC-217) ---
68	  await openAddBudget(page);
69	  let c = await combo(page, 1);
70	  await page.mouse.click(c.x, c.y);
71	  await new Promise((r) => setTimeout(r, 300));
72	  await page.keyboard.press("Escape");
73	  await new Promise((r) => setTimeout(r, 300));
74	  out.escape1 = await state(page); // want dialog true, listbox false
75	  await page.keyboard.press("Escape");
76	  await new Promise((r) => setTimeout(r, 300));
77	  out.escape2 = await state(page); // want dialog false
78	
79	  // --- Search behaviour on the Parent/category picker ---
80	  await openAddBudget(page);
81	  c = await combo(page, 0); // parent picker
82	  await page.mouse.click(c.x, c.y);
83	  await new Promise((r) => setTimeout(r, 400));
84	  out.search = await page.evaluate(() => {
85	    const listbox = document.querySelector('[role="listbox"]');
86	    const input = listbox?.querySelector("input");
87	    const items = () => [...listbox.querySelectorAll('[role="option"]')].map((o) => o.textContent.trim());
88	    return {
89	      hasSearchInput: Boolean(input),
90	      inputFocused: document.activeElement === input,
91	      order: items(),
92	    };
93	  });
94	  // type a query
95	  await page.keyboard.type("gro");
96	  await new Promise((r) => setTimeout(r, 250));
97	  out.filtered = await page.evaluate(() => {
98	    const listbox = document.querySelector('[role="listbox"]');
99	    return {
100	      items: [...listbox.querySelectorAll('[role="option"]')].map((o) => o.textContent.trim()),
101	      dialogStillOpen: Boolean(document.querySelector('[role="dialog"]')),
102	    };
103	  });
104	  // Enter selects first visible (ISC-245)
105	  await page.keyboard.press("Enter");
106	  await new Promise((r) => setTimeout(r, 300));
107	  out.afterEnter = await page.evaluate(() => {
108	    const dlg = document.querySelector('[role="dialog"]');
109	    const trigger = dlg?.querySelectorAll('[role="combobox"]')[0];
110	    return {
111	      listboxClosed: !document.querySelector('[role="listbox"]'),
112	      dialogOpen: Boolean(dlg),
113	      triggerText: trigger?.textContent?.trim(),
114	    };
115	  });
116	
117	  // --- No matches + reset on close (ISC-231/232) ---
118	  c = await combo(page, 0);
119	  await page.mouse.click(c.x, c.y);
120	  await new Promise((r) => setTimeout(r, 300));
121	  await page.keyboard.type("zzzz");
122	  await new Promise((r) => setTimeout(r, 250));
123	  out.noMatches = await page.evaluate(() => {
124	    const listbox = document.querySelector('[role="listbox"]');
125	    return { text: listbox?.textContent?.includes("No matches"), optionCount: listbox?.querySelectorAll('[role="option"]').length };
126	  });
127	  await page.keyboard.press("Escape");
128	  await new Promise((r) => setTimeout(r, 300));
129	  c = await combo(page, 0);
130	  await page.mouse.click(c.x, c.y);
131	  await new Promise((r) => setTimeout(r, 300));
132	  out.afterReopen = await page.evaluate(() => {
133	    const listbox = document.querySelector('[role="listbox"]');
134	    return {
135	      inputValue: listbox?.querySelector("input")?.value,
136	      optionCount: listbox?.querySelectorAll('[role="option"]').length,
137	      firstItem: listbox?.querySelector('[role="option"]')?.textContent?.trim(),
138	    };
139	  });
