const { visible, hiddenSelected } = React.useMemo(() => {
  const q = query.trim().toLowerCase();
  const matches = (o: SearchableSelectOption) => !q || o.label.toLowerCase().includes(q);
  const tops = options.filter((o) => o.pin === "top" && matches(o));
  const bottoms = options.filter((o) => o.pin === "bottom" && matches(o));
  let mids = options.filter((o) => !o.pin && matches(o));
  if (sort) {
    const groupOrder = [...new Set(options.filter((o) => !o.pin).map((o) => o.group ?? ""))];
    mids = groupOrder.flatMap((g) => mids.filter((o) => (o.group ?? "") === g).sort(labelCompare));
  }
  const shown = [...tops, ...mids, ...bottoms];
  // The SELECTED option must stay mounted even when filtered out — Radix
  // renders the trigger's value from the selected item's text — but it
  // renders hidden so a no-match query still reads "No matches".
  const selected = options.find((o) => o.value === selectedValue);
  return {
    visible: shown,
    hiddenSelected: selected && !shown.some((o) => o.value === selected.value) ? selected : null,
  };
}, [options, query, sort, selectedValue]);

