  setOpen(false);
  // Closing restores the page's pointer events mid-gesture, so the same
  // gesture's trailing click would land on whatever the close reveals —
  // usually the trigger, silently REOPENING the dropdown. One gesture
  // closes one layer: swallow that click.
  const swallow = (ce: MouseEvent) => {
    ce.stopPropagation();
    ce.preventDefault();
  };
  document.addEventListener("click", swallow, { capture: true, once: true });
  setTimeout(() => document.removeEventListener("click", swallow, { capture: true }), 600);
};

input.new_string:
  setOpen(false);
  // Closing restores the page's pointer events mid-gesture, so the same
  // gesture's trailing click would land on whatever the close reveals —
  // usually the trigger, silently REOPENING the dropdown. One gesture
  // closes one layer: swallow that click. Disarm on the NEXT pointerdown
  // (a new gesture means the old trailing click is not coming — iOS can
  // skip it entirely) and after 600ms, so a later real tap is never eaten.
  const swallow = (ce: MouseEvent) => {
    ce.stopPropagation();
    ce.preventDefault();
    disarm();
  };
  const onNextGesture = () => disarm();
  function disarm() {
    document.removeEventListener("click", swallow, { capture: true });
    document.removeEventListener("pointerdown", onNextGesture, { capture: true });
  }
  document.addEventListener("click", swallow, { capture: true });
  // Listeners added during dispatch don't run for the current event, so
  // this arms for the FOLLOWING pointerdown, not this one.
  document.addEventListener("pointerdown", onNextGesture, { capture: true });
  setTimeout(disarm, 600);
};

