1	/**
2	 * Reconcile route handler (ISC-37, ISC-43): confirms the Credit Card Holding
3	 * envelope matches the entered NAB statement balance as at the statement date,
4	 * and reports the drift (the named euphoric tripwire). Scoped to the user.
5	 */
6	
7	import { Hono } from "hono";
8	import type { Container } from "../../composition.ts";
9	import type { Services } from "../services.ts";
10	import type {
11	  LastReconcileResponse,
12	  NetPositionResponse,
13	  ReconcileBalanceLine,
14	  ReconcileBalancesResponse,
15	  ReconcileConfirmation,
16	  ReconcileConfirmResponse,
17	  ReconcileResponse,
18	} from "../contract.ts";
19	import type { ReconciliationRecord } from "../../budget/ports.ts";
20	import { currentPeriod, resolveSession, UNAUTHENTICATED } from "../http.ts";
21	import { parseBody, reconcileSchema, reconcileConfirmSchema } from "../validate.ts";
22	import { PocketSmithClient } from "../../ingest/client.ts";
23	import { buildBalanceLines, type ReconcileAccount } from "../../reconcile/balances.ts";
24	
25	export function registerReconcile(api: Hono, container: Container, services: Services): void {
26	  api.post("/reconcile", async (c) => {
27	    const session = await resolveSession(c, container);
28	    if (!session) return c.json(UNAUTHENTICATED, 401);
29	    const parsed = await parseBody(c, reconcileSchema);
30	    if (!parsed.ok) return parsed.response;
31	    const req = parsed.value;
32	    const asOf = req.statementDate;
33	    const holdingCents = await services.envelopes.holdingBalance(
34	      session.userId,
35	      asOf || undefined,
36	    );
37	    const nabStatementCents = req.nabStatementCents;
38	    const driftCents = holdingCents - nabStatementCents;
39	    const res: ReconcileResponse = {
40	      holdingCents,
41	      nabStatementCents,
42	      driftCents,
43	      matched: driftCents === 0,
44	    };
45	    return c.json(res);
46	  });
47	
48	  /**
49	   * Persist a reconciliation confirmation (Phase 4, ISC-37). The holding balance
50	   * and drift are recomputed server-side from the engine — the client-sent NAB
51	   * figure is the only input trusted — so a recorded confirmation reflects the
52	   * system's own numbers, never a fabricated or client-forged figure (ISC-83).
53	   */
54	  const toRecordResponse = (rec: ReconciliationRecord): ReconcileConfirmation => ({
55	    id: rec.id,
56	    confirmedAt: rec.ts,
57	    statementDate: rec.statementDate,
58	    holdingCents: rec.holdingCents,
59	    nabStatementCents: rec.nabStatementCents,
60	    driftCents: rec.driftCents,
61	    matched: rec.matched,
62	  });
63	
64	  api.post("/reconcile/confirm", async (c) => {
65	    const session = await resolveSession(c, container);
66	    if (!session) return c.json(UNAUTHENTICATED, 401);
67	    const parsed = await parseBody(c, reconcileConfirmSchema);
68	    if (!parsed.ok) return parsed.response;
69	    const req = parsed.value;
70	    const holdingCents = await services.envelopes.holdingBalance(
71	      session.userId,
72	      req.statementDate || undefined,
73	    );
74	    const driftCents = holdingCents - req.nabStatementCents;
75	    const rec: ReconciliationRecord = {
76	      id: crypto.randomUUID(),
77	      ts: Date.now(),
78	      statementDate: req.statementDate,
79	      holdingCents,
80	      nabStatementCents: req.nabStatementCents,
81	      driftCents,
82	      matched: driftCents === 0,
83	    };
84	    await container.store.appendReconciliation(session.userId, rec);
85	    const res: ReconcileConfirmResponse = { ok: true, confirmation: toRecordResponse(rec) };
86	    return c.json(res);
87	  });
88	
89	  api.get("/reconcile/last", async (c) => {
90	    const session = await resolveSession(c, container);
91	    if (!session) return c.json(UNAUTHENTICATED, 401);
92	    const latest = await container.store.getLatestReconciliation(session.userId);
93	    const res: LastReconcileResponse = { confirmation: latest ? toRecordResponse(latest) : null };
94	    return c.json(res);
95	  });
96	
97	  /**
98	   * Penny vs PocketSmith balance reconciliation (P0 trust surface). Pulls the
99	   * tenant's PocketSmith account balances live and compares each to Penny's
100	   * computed per-account figure, anchored on the Credit Card Holding vs card
101	   * tripwire (ISC-37, ISC-43) and generalised across every tracked account. On
102	   * any failure (no key, network/auth) it returns ok:false with a key-free reason
103	   * so the screen degrades to a clear "could not reach PocketSmith" state rather
104	   * than erroring. The developer key is resolved through the SecretStore inside
105	   * forUser and never reaches the response (ISC-56).
106	   */
107	  api.get("/reconcile/balances", async (c) => {
108	    const session = await resolveSession(c, container);
109	    if (!session) return c.json(UNAUTHENTICATED, 401);
110	
111	    const fail = (message: string): ReconcileBalancesResponse => ({
112	      ok: false,
113	      lines: [],
114	      cardDriftCents: 0,
115	      asOf: Date.now(),
116	      message,
117	    });
118	
119	    try {
120	      const client = await PocketSmithClient.forUser(container.secrets, session.userId);
121	      const user = await client.getAuthenticatedUser();
122	      if (user.id === undefined || user.id === null) {
123	        return c.json(fail("PocketSmith did not return an account id."));
124	      }
125	      const [accounts, txs] = await Promise.all([
126	        client.listTransactionAccounts(user.id),
127	        container.store.listTransactions(session.userId),
128	      ]);
129	      const accIn: ReconcileAccount[] = accounts.map((a) => ({
130	        id: String(a.id),
131	        title: a.name ?? `Account ${a.id}`,
132	        type: a.type ?? "",
133	        currentBalance: a.current_balance,
134	      }));
135	      const lines: ReconcileBalanceLine[] = buildBalanceLines(
136	        accIn,
137	        txs.map((t) => ({ accountId: t.accountId, amountCents: t.amountCents, isPending: t.isPending })),
138	        services.engineConfig.nabCardAccountIds,
139	      );
140	      const cardDriftCents = lines
141	        .filter((l) => l.kind === "card")
142	        .reduce((s, l) => s + l.driftCents, 0);
143	      const res: ReconcileBalancesResponse = { ok: true, lines, cardDriftCents, asOf: Date.now() };
144	      return c.json(res);
145	    } catch {
146	      // Never surface the underlying error verbatim: it could narrow the key.
147	      return c.json(fail("Could not reach PocketSmith. Check the developer key in Settings."));
148	    }
149	  });
150	
151	  /**
152	   * Net-position master reconciliation (the whole point of envelope budgeting).
153	   * Pulls the tenant's live PocketSmith account balances and reconciles the real
154	   * liquid position (cash on hand minus what is owed on credit cards) against the
155	   * budget's total "left" (sum of leaf-envelope leftCents plus income leftCents).
156	   *
157	   * Account classification mirrors the balances surface but is coarser by design:
158	   * any account whose type contains "credit" is a card (its balance is negative,
159	   * so we report the owed amount as a positive magnitude); everything else
160	   * (bank, cash) is cash on hand. Only LEAF envelopes are summed so the rolled-up
161	   * parent rows are not double-counted.
162	   *
163	   * On any PocketSmith failure it returns ok:false with a key-free reason (ISC-56),
164	   * mirroring the balances handler, so the widget degrades cleanly.
165	   */
166	  api.get("/net-position", async (c) => {
167	    const session = await resolveSession(c, container);
168	    if (!session) return c.json(UNAUTHENTICATED, 401);
169	
170	    const fail = (message: string): NetPositionResponse => ({
171	      ok: false,
172	      cashOnHandCents: 0,
173	      cardOwedCents: 0,
174	      totalLeftCents: 0,
175	      sectionLeftCents: { income: 0, saving: 0, expense: 0, envelope: 0, working: 0 },
176	      reconciledDeltaCents: 0,
177	      asOf: Date.now(),
178	      message,
179	    });
180	
181	    // Decimal-dollar PocketSmith balance to integer cents, rounding float dust.
182	    const toCents = (amount: number | undefined | null): number =>
183	      amount === undefined || amount === null || Number.isNaN(amount) ? 0 : Math.round(amount * 100);
184	
185	    try {
186	      const client = await PocketSmithClient.forUser(container.secrets, session.userId);
187	      const user = await client.getAuthenticatedUser();
188	      if (user.id === undefined || user.id === null) {
189	        return c.json(fail("PocketSmith did not return an account id."));
190	      }
191	      const accounts = await client.listTransactionAccounts(user.id);
192	
193	      let cashOnHandCents = 0;
194	      let cardBalanceCents = 0; // signed; cards report a negative balance.
195	      for (const a of accounts) {
196	        const isCard = (a.type ?? "").toLowerCase().includes("credit");
197	        const cents = toCents(a.current_balance);
198	        if (isCard) cardBalanceCents += cents;
199	        else cashOnHandCents += cents;
200	      }
201	      // Card balances are negative; owed is the magnitude reported positive.
202	      const cardOwedCents = Math.abs(cardBalanceCents);
203	
204	      // Total "left": sum of TOP-LEVEL rows, whose leftCents roll up their
205	      // descendants — every envelope counted exactly once INCLUDING a parent's
206	      // OWN balance. (The previous leaves-only sum dropped parents' own money
207	      // entirely — Recreation's own −$5,674 vanished from the reconciliation,
208	      // making this widget disagree with the budget page by that amount.)
209	      const grid = await services.envelopes.getGrid(session.userId, currentPeriod(container.config.timezone));
210	      // Working envelopes sit outside the ZERO-BASE budget but still move real cash,
211	      // so they ARE part of the net-position reconciliation as their own section line
212	      // (their balance begins at 0 today and accrues forward).
213	      const topLevel = grid.rows.filter((r) => r.parentId === null);
214	      const leafLeftCents = topLevel.reduce((s, r) => s + r.leftCents, 0);
215	      // Income contributes carryover + surplus/deficit (variance), NOT carryover +
216	      // received. The budgeted income is already represented in the expense envelopes'
217	      // allocations (zero-base), so including the full received here would double-count
218	      // the budget. carry + (received - budget) makes the budgets cancel and the sum
219	      // reconcile to cash - card. The income row's own "left" stays carry + received.
220	      const incomeLeftCents = grid.income.reduce((s, i) => s + i.carryoverCents + i.varianceCents, 0);
221	      const totalLeftCents = leafLeftCents + incomeLeftCents;
222	      // D5: pre-payday, due-based variance holds back the not-yet-due income;
223	      // the cash hasn't arrived either, so the reconciliation compensates with
224	      // the awaiting total to stay exact across the expected-day boundary.
225	      const awaitingIncomeCents = grid.income.reduce((s, i) => s + (i.awaitingCents ?? 0), 0);
226	
227	      // Per-section "left": income from the income envelopes, and each spending
228	      // type from its leaf rows, so the four figures sum to totalLeftCents.
229	      const leftByType = (type: string): number =>
230	        topLevel.filter((r) => r.type === type).reduce((s, r) => s + r.leftCents, 0);
231	      const sectionLeftCents = {
232	        income: incomeLeftCents,
233	        saving: leftByType("saving"),
234	        expense: leftByType("expense"),
235	        envelope: leftByType("envelope"),
236	        working: leftByType("working"),
237	      };
238	
239	      const reconciledDeltaCents = cashOnHandCents - cardOwedCents - (totalLeftCents - awaitingIncomeCents);
240	      const res: NetPositionResponse = {
241	        ok: true,
242	        cashOnHandCents,
243	        cardOwedCents,
244	        totalLeftCents,
245	        awaitingIncomeCents,
246	        sectionLeftCents,
247	        reconciledDeltaCents,
248	        asOf: Date.now(),
249	      };
250	      return c.json(res);
251	    } catch {
252	      // Never surface the underlying error verbatim: it could narrow the key.
253	      return c.json(fail("Could not reach PocketSmith. Check the developer key in Settings."));
254	    }
255	  });
256	}
