/**
 * On-demand sync handler (Phase 4, ISC-5/7/8). Triggers the SAME incremental
 * pull the daily cron runs (scripts/sync.ts) for the authenticated user, so the
 * Settings "Sync now" button is backed by a real endpoint rather than a
 * fabricated timer (ISC-83).
 *
 * The PocketSmith developer key is resolved through the SecretStore inside
 * forUser and never reaches the response (ISC-56). On any failure (no key,
 * network/auth) it returns ok:false with a safe, key-free reason so the UI shows
 * a clear error instead of inventing progress.
 */

import { Hono } from "hono";
import type { Container } from "../../composition.ts";
import type { SyncNowResponse } from "../contract.ts";
import { resolveSession, UNAUTHENTICATED } from "../http.ts";
import { PocketSmithClient } from "../../ingest/client.ts";
import { runSync } from "../../ingest/sync.ts";

export function registerSync(api: Hono, container: Container): void {
  api.post("/sync", async (c) => {
    const session = await resolveSession(c, container);
    if (!session) return c.json(UNAUTHENTICATED, 401);

    const fail = (message: string): SyncNowResponse => ({
      ok: false,
      transactions: 0,
      pages: 0,
      lastSyncAt: null,
      message,
    });

    try {
      const client = await PocketSmithClient.forUser(container.secrets, session.userId);
      const result = await runSync({ store: container.store, client, userId: session.userId });
      const res: SyncNowResponse = {
        ok: true,
        transactions: result.transactions,
        pages: result.pages,
        lastSyncAt: result.completedAt,
      };
      return c.json(res);
    } catch {
      // Never surface the underlying error verbatim: it could narrow the key.
      return c.json(fail("Could not sync. Check the PocketSmith developer key in Settings."));
    }
  });
}

