// Same read path the UI uses: grid + zero-base + net-position components.
import { buildContainer } from "/home/nicholas-wood/Documents/workspace/projects/envelope-os/src/composition.ts";
import { buildServices } from "/home/nicholas-wood/Documents/workspace/projects/envelope-os/src/server/services.ts";
import { PocketSmithClient } from "/home/nicholas-wood/Documents/workspace/projects/envelope-os/src/ingest/client.ts";

const container = await buildContainer();
const services = buildServices(container);
const grid = await services.envelopes.getGrid("local", "this-month");
const cents = (n: number) => (n / 100).toFixed(2);

console.log("unallocatedCents:", cents((grid as any).unallocatedCents ?? NaN), "zeroBasedAlert:", (grid as any).zeroBasedAlert);

// Net position, same maths as the handler
const client = await PocketSmithClient.forUser(container.secrets, "local");
const me = await client.getAuthenticatedUser();
const accounts = await client.listTransactionAccounts(me.id!);
let cash = 0, card = 0;
for (const a of accounts) {
  const c = a.current_balance ? Math.round(a.current_balance * 100) : 0;
  if ((a.type ?? "").toLowerCase().includes("credit")) card += c; else cash += c;
}
const top = grid.rows.filter((r: any) => r.parentId === null);
const leafLeft = top.reduce((s: number, r: any) => s + r.leftCents, 0);
const incomeLeft = grid.income.reduce((s: number, i: any) => s + i.carryoverCents + i.varianceCents, 0);
const awaiting = grid.income.reduce((s: number, i: any) => s + (i.awaitingCents ?? 0), 0);
const totalLeft = leafLeft + incomeLeft;
const delta = cash - Math.abs(card) - (totalLeft - awaiting);
console.log(JSON.stringify({
  cashOnHand: cents(cash), cardOwed: cents(Math.abs(card)),
  leafLeft: cents(leafLeft), incomeLeft: cents(incomeLeft), awaiting: cents(awaiting),
  totalLeft: cents(totalLeft), reconciledDelta: cents(delta),
}, null, 1));
// Income envelope detail — the 20k inflow's likely landing zone
for (const i of grid.income as any[]) {
  console.log("income:", i.name, "carry", cents(i.carryoverCents), "received", cents(i.receivedCents ?? NaN), "variance", cents(i.varianceCents), "awaiting", cents(i.awaitingCents ?? 0));
}
await container.store.close?.();
EOF
