// Per-account: starting_balance + Σ posted txns after starting date ?= current_balance.
// Residual = bank-side movement with NO transaction (feed adjustment / gap creep).
import { PocketSmithClient } from "/home/nicholas-wood/Documents/workspace/projects/envelope-os/src/ingest/client.ts";
import { LocalSecretStore } from "/home/nicholas-wood/Documents/workspace/projects/envelope-os/src/platform/secrets/local.ts";
import { Database } from "bun:sqlite";

const client = await PocketSmithClient.forUser(new LocalSecretStore(), "local");
const me = await client.getAuthenticatedUser();
const accounts = await client.listTransactionAccounts(me.id!);
const db = new Database("/home/nicholas-wood/.penny/penny.db", { readonly: true });
const cents = (n: number | undefined | null) => (n == null || Number.isNaN(n) ? 0 : Math.round(n * 100));
const fmt = (n: number) => (n / 100).toFixed(2);

let totalResidual = 0;
for (const a of accounts) {
  const id = String(a.id);
  const posted = db.query(
    "SELECT COUNT(*) n, COALESCE(SUM(amount_cents),0) net FROM transactions WHERE account_id = ?1 AND is_pending = 0 AND txn_date > ?2",
  ).get(id, a.starting_balance_date ?? "1970-01-01") as { n: number; net: number };
  const pend = db.query(
    "SELECT COALESCE(SUM(amount_cents),0) net FROM transactions WHERE account_id = ?1 AND is_pending = 1",
  ).get(id) as { net: number };
  const start = cents(a.starting_balance);
  const cur = cents(a.current_balance);
  const isCard = (a.type ?? "").toLowerCase().includes("credit");
  // NAB card balance includes pendings (verified in the drift work); others don't.
  const pendingAdj = id === "4771153" ? pend.net : 0;
  const residual = cur - (start + posted.net + pendingAdj);
  totalResidual += residual;
  if (Math.abs(residual) > 100 || posted.n > 0)
    console.log(
      `${(a.name ?? id).padEnd(32)} start ${fmt(start).padStart(10)} (${a.starting_balance_date})  txns ${String(posted.n).padStart(4)} net ${fmt(posted.net).padStart(11)}  now ${fmt(cur).padStart(10)}  RESIDUAL ${fmt(residual).padStart(9)}${isCard ? "  [card]" : ""}`,
    );
}
console.log("\nTOTAL residual (bank moved without transactions):", fmt(totalResidual));
EOF
