import { Database } from "bun:sqlite";

const container = await buildContainer();
const services = buildServices(container);
const client = await PocketSmithClient.forUser(container.secrets, "local");
const me = await client.getAuthenticatedUser();
const accounts = await client.listTransactionAccounts(me.id!);
const db = new Database("/home/nicholas-wood/.penny/penny.db", { readonly: true });
const fmt = (n: number) => (n / 100).toFixed(2);

// Live pendings all dated ≥ 2026-08-11, so for month-end reconstruction before
// August they are simply excluded; NAB current balance includes them.
const pendNet = (db.query("SELECT COALESCE(SUM(amount_cents),0) net FROM transactions WHERE is_pending = 1").get() as any).net;

function balancesAt(dateIso: string): { cash: number; cardOwed: number } {
  let cash = 0, card = 0;
  for (const a of accounts) {
    const id = String(a.id);
    const cur = a.current_balance ? Math.round(a.current_balance * 100) : 0;
    const after = (db.query(
      "SELECT COALESCE(SUM(amount_cents),0) net FROM transactions WHERE account_id = ?1 AND is_pending = 0 AND txn_date > ?2",
    ).get(id, dateIso) as any).net;
    let bal = cur - after;
    if (id === "4771153") bal -= pendNet; // strip today's pendings from the card's live balance
    if ((a.type ?? "").toLowerCase().includes("credit")) card += bal;
    else cash += bal;
  }
  return { cash, cardOwed: Math.abs(card) };
}

for (const [label, dateIso, period] of [
  ["2026-06-30", "2026-06-30", { year: 2026, month: 6 }],
  ["2026-07-31", "2026-07-31", { year: 2026, month: 7 }],
] as const) {
  const { cash, cardOwed } = balancesAt(dateIso);
  const grid = await services.envelopes.getGrid("local", period as any);
  const top = grid.rows.filter((r: any) => r.parentId === null);
  const leafLeft = top.reduce((s: number, r: any) => s + r.leftCents, 0);
  const incomeLeft = grid.income.reduce((s: number, i: any) => s + i.carryoverCents + i.varianceCents, 0);
  const awaiting = grid.income.reduce((s: number, i: any) => s + (i.awaitingCents ?? 0), 0);
  const delta = cash - cardOwed - (leafLeft + incomeLeft - awaiting);
  console.log(`${label}: cash ${fmt(cash)}  cardOwed ${fmt(cardOwed)}  left ${fmt(leafLeft + incomeLeft)}  awaiting ${fmt(awaiting)}  DELTA ${fmt(delta)}`);
}
console.log("today    : DELTA 452.29 displayed (= 1051.84 structural − 599.55 pending mask)");
await container.store.close?.();
EOF
