const envs = new Map((db.query("SELECT id, name, type, parent_id FROM envelopes").all() as any[]).map((e) => [String(e.id), e]));

const envAt = (cat: string | null, date: string): string | null => {
  if (cat === null) return null;
  const m = mappings.find((m) => m.category_id === String(cat) && m.effective_from <= date && (m.effective_to === null || m.effective_to >= date));
