  // (includePending). Transfers stay excluded. The holding tripwire
  // (holdingBalance) and reconcile keep the posted-only rule, so this does
  // not move any bank-reconciliation figure.
  const activity = computeActivity(txs, mappings, this.config, {
    period: p,
    includePending: true,
    ...(isFinal && asOf !== undefined ? { asOf } : {}),
  });
  // Movements are signed activity in the month they happened (line items).
  const activityByEnv = new Map(activity.byEnvelope);
  const monthMoves = movementByMonth.get(periodKey(p));
  if (monthMoves !== undefined) {
    for (const [envId, v] of monthMoves) {
      activityByEnv.set(envId, (activityByEnv.get(envId) ?? 0) + v);
    }
  }
  inputs.push({ period: p, allocationByEnv, activityByEnv });
}

